<script lang="ts">
  import { onMount } from 'svelte';
  import SearchDiagnostics from './SearchDiagnostics.svelte';
  import StudyLab from './StudyLab.svelte';
  type Dataset = { id: string; name: string; synthetic: boolean; researchOnly?: boolean; researchOnlyReason?: string; months: number; assets: number; start: string; end: string };
  type Run = { id: string; datasetId: string; datasetName: string; synthetic: boolean; status: string; createdAt: string; progress: number; errorCode: string | null; config: { hypothesis: string; topK: number; maximumWeight: number; monthlyGbp: number } };
  type Summary = { strategy: string; endingEquityGbp: number; contributionsGbp: number; profitGbp: number; tradingCostGbp: number; maxDrawdown: number; annualisedTimeWeightedReturn: number; tradedNotionalGbp: number };
  type Equity = { periodEnd: string; strategy: string; state: { equityGbp: number; contributionsGbp: number; cashGbp: number } };
  type Point = { year: number; contributionsGbp: number; lowerBalanceGbp: number; medianBalanceGbp: number; upperBalanceGbp: number };
  type Report = { config: { allocationPolicy: string }; synthetic: boolean; researchOnly?: boolean; researchOnlyReason?: string; source: string; datasetSha256: string; featureVersion: string; scope: string; evaluationStart: string; evaluationEnd: string; reservedPeriodStart: string; summaries: Summary[]; equity: Equity[]; predictions: { decisionDate: string; featureCutoff: string; symbol: string; score: number; targetWeight: number }[]; forward: { method: string; points: Point[] }; limitations: string[] };
  let datasets = $state<Dataset[]>([]), runs = $state<Run[]>([]), selected = $state<Run | null>(null), report = $state<Report | null>(null);
  let datasetId = $state(''), hypothesis = $state('ridge-relative-return'), allocationPolicy = $state('contribution-only'), topK = $state(3), cap = $state(50), monthly = $state(20), forwardYears = $state(10), alpha = $state(10), fxBps = $state(15), taxBps = $state(0), busy = $state(false), error = $state('');
  let requestId = '';
  let totalTrials = $state(0);
  const labels: Record<string,string> = { candidate: 'Selected strategy', momentum: 'Momentum comparator', equal_weight: 'All assets equally', benchmark: 'Dataset benchmark', cash: 'Uninvested cash' };
  const methods: Record<string,string> = { 'ridge-relative-return': 'Train a relative-return model', momentum: 'Rank long momentum', breakout: '12-month return-index breakout', 'upside-tail': 'Model +50% upside over six months', 'core-satellite': 'Half equal-weight core, half momentum satellite', 'sleeve-blend': 'Split each contribution across strategy sleeves' };
  let sleeveSpec = $state('benchmark:0.7,core-satellite:0.3');
  const money = (x: number) => new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:2}).format(x);
  const pct = (x: number) => `${(x*100).toFixed(1)}%`;
  const dataset = $derived(datasets.find(d=>d.id===datasetId));
  const active = $derived(runs.some(r=>r.status==='queued'||r.status==='running'));
  const candidate = $derived(report?.summaries.find(s=>s.strategy==='candidate'));
  const lastDate = $derived(report?.predictions.at(-1)?.decisionDate);
  const picks = $derived(report?.predictions.filter(p=>p.decisionDate===lastDate).sort((a,b)=>b.score-a.score) ?? []);
  const chartRows = $derived(report?.equity.filter(e=>e.strategy==='candidate') ?? []);
  const chartMax = $derived(Math.max(1,...(report?.equity.map(e=>e.state.equityGbp)??[1])));
  const forwardMax = $derived(Math.max(1,...(report?.forward.points.map(p=>p.upperBalanceGbp)??[1])));
  function curve(strategy:string) { const rows=report?.equity.filter(e=>e.strategy===strategy)??[]; return rows.map((e,i)=>`${45+i/Math.max(1,rows.length-1)*710},${220-e.state.equityGbp/chartMax*185}`).join(' '); }
  function forwardLine(key:'lowerBalanceGbp'|'medianBalanceGbp'|'upperBalanceGbp'|'contributionsGbp') { const rows=report?.forward.points??[]; return rows.map((e,i)=>`${45+i/Math.max(1,rows.length-1)*710},${220-e[key]/forwardMax*185}`).join(' '); }
  const band = $derived(`${forwardLine('upperBalanceGbp')} ${forwardLine('lowerBalanceGbp').split(' ').reverse().join(' ')}`);
  async function api(path:string, init?:RequestInit) { const response=await fetch(path,init); if(!response.ok){let code='service-unavailable';try{code=(await response.json()).error??code;}catch{}throw new Error(code);}return response.status===202?response.json().catch(()=>null):response.json(); }
  async function refresh() {
    try { const [history,stats]=await Promise.all([api('/api/research/runs'),api('/api/research/trials')]);runs=history;totalTrials=stats.total; if(selected){selected=runs.find(r=>r.id===selected!.id)??selected;if(selected.status==='succeeded'&&!report){const id=selected.id;const result=await api(`/api/research/runs/${id}/report`);if(selected?.id===id)report=result;}} }
    catch(e){error=e instanceof Error?e.message:'service-unavailable';}
  }
  async function inspect(run:Run) { selected=run;report=null;error='';if(run.status==='succeeded'){try{const result=await api(`/api/research/runs/${run.id}/report`);if(selected?.id===run.id)report=result;}catch(e){error=e instanceof Error?e.message:'report-unavailable';}} }
  async function inspectStudyRun(id:string){try{await inspect(await api(`/api/research/runs/${id}`));}catch(e){error=e instanceof Error?e.message:'report-unavailable';}}
  async function start(count=topK, maximum=cap) {
    busy=true;error='';requestId ||= crypto.randomUUID();
    if(hypothesis==='sleeve-blend'){const parts=sleeveSpec.split(',').map(p=>p.trim()).filter(Boolean);const total=parts.reduce((sum,p)=>sum+Number(p.split(':')[1]),0);if(!parts.length||parts.some(p=>p.split(':').length!==2)||Math.abs(total-1)>0.000001){error='Sleeve fractions must be named shares summing to 1, e.g. benchmark:0.7,core-satellite:0.3';busy=false;return;}}
    try {
      const run:Run=await api('/api/research/runs',{method:'POST',headers:{'Content-Type':'application/json','X-Twenty-Request':'1'},body:JSON.stringify({requestId,datasetId,config:{monthlyGbp:monthly,topK:count,maximumWeight:maximum/100,trainMonths:60,refitMonths:12,holdoutMonths:24,ridgeAlpha:alpha,hypothesis,evaluateHoldout:false,forwardYears,seed:212,allocationPolicy,sleeveSpec:hypothesis==='sleeve-blend'?sleeveSpec:''},costs:{fxBps,halfSpreadBps:5,slippageBps:5,buyTaxBps:taxBps,minimumOrderGbp:1}})});
      requestId='';selected=run;report=null;await refresh();
    }catch(e){error=e instanceof Error?e.message:'run-not-created';}finally{busy=false;}
  }
  async function compare() { for(const n of [1,2,4,8]) { await start(n,100/n); if(error)break; } }
  async function cancel(run:Run){try{await api(`/api/research/runs/${run.id}/cancel`,{method:'POST',headers:{'X-Twenty-Request':'1'}});await refresh();}catch(e){error=e instanceof Error?e.message:'cancel-failed';}}
  onMount(()=>{
    let stopped=false;
    void api('/api/research/datasets').then((data:Dataset[])=>{datasets=data;datasetId=data.find(d=>d.name.includes('growth'))?.id??data[0]?.id??'';}).catch(()=>error='Datasets could not be loaded.');
    void refresh();
    const timer=setInterval(()=>{if(!stopped&&(active||!selected))void refresh();},1500);
    return()=>{stopped=true;clearInterval(timer);};
  });
</script>

<div class="page-heading"><div><p class="eyebrow">SPECULATIVE GROWTH RESEARCH</p><h1>Find the upside.<br/><em>Measure what can go wrong.</em></h1><p class="intro">Train a model. Test its stock choices. Compare concentration and costs.<br/>Every attempt stays in the experiment record.</p></div><div class="mode-stamp"><span>WORKING RESEARCH LAB</span><strong>Native CPU<br/>model training</strong><small>Backtest accounting: simulation</small></div></div>
<div class="lab-layout">
<section class="panel lab-config" aria-labelledby="experiment-title"><p class="eyebrow">NEW EXPERIMENT</p><h2 id="experiment-title">Put a hypothesis to work.</h2>
<form onsubmit={(e)=>{e.preventDefault();void start();}}>
<label>Research dataset<select bind:value={datasetId} required>{#each datasets as d}<option value={d.id}>{d.name}</option>{/each}</select></label>
{#if dataset}<p class="dataset-note">{dataset.assets} assets · {dataset.months} months · {dataset.start}–{dataset.end}<br/>{dataset.researchOnly?dataset.researchOnlyReason:dataset.synthetic?'Synthetic engineering data. No real stock-performance claim.':'Imported fixed-universe panel. Historical coverage is not certified.'}</p>{/if}
<label>Stock-selection hypothesis<select bind:value={hypothesis}>{#each Object.entries(methods) as [key,label]}<option value={key}>{label}</option>{/each}</select></label>
<label>Allocation policy<select bind:value={allocationPolicy}><option value="contribution-only">Add contributions and retain holdings</option><option value="full-rebalance">Rebalance by selling and buying</option></select></label>
{#if hypothesis==='sleeve-blend'}<label>Strategy sleeves (shares of each contribution)<input type="text" bind:value={sleeveSpec} required/></label><p class="dataset-note">Sleeves: benchmark, equal_weight, cash, momentum, breakout, core-satellite, ridge-relative-return. Shares must sum to 1. The market sleeve is not capped by the purchase target; selection names are.</p>{/if}
<div class="lab-pair"><label>Monthly contribution (£)<input type="number" min="1" max="1000" step="1" bind:value={monthly} required/></label><label>Selected holdings<input type="number" min="1" max="10" step="1" bind:value={topK} required/></label></div>
<div class="lab-pair"><label>Maximum purchase target (%)<input type="number" min="1" max="100" step="1" bind:value={cap} required/></label><label>Forward scenario (years)<input type="number" min="1" max="30" bind:value={forwardYears} required/></label></div>
<details><summary>Model and cost assumptions</summary><div class="lab-pair"><label>Ridge regularisation<input type="number" min="0.01" max="1000" bind:value={alpha} step="0.01" required/></label><label>FX cost per side (bps)<input type="number" min="0" max="500" bind:value={fxBps} required/></label><label>Purchase tax (bps)<input type="number" min="0" max="500" bind:value={taxBps} required/></label></div><p class="dataset-note">60 training months; annual refits; final 24 months reserved. Spread 5 bps + slippage 5 bps per side; £1 minimum. These are flat research assumptions.</p></details>
<button type="submit" disabled={busy||!datasetId}>{busy?'Recording experiment…':'Train and backtest'} <span aria-hidden="true">↗</span></button>
<button type="button" class="secondary" disabled={busy||!datasetId||active} onclick={()=>void compare()}>Compare 1, 2, 4 and 8 holdings</button>
<p class="dataset-note">Contribution-only retains holdings: appreciation can exceed targets, and occupied slots can leave new contributions as cash. Concentration is an experiment, not a recommended allocation. A broad benchmark and cash stay in every comparison.</p>
</form></section>
<section class="panel lab-history" aria-labelledby="history-title"><div class="panel-heading"><div><p class="eyebrow">TRIAL REGISTER</p><h2 id="history-title">Experiment history</h2></div><span class="badge">{totalTrials} registered · 1 job at a time</span></div>
{#if totalTrials>runs.length}<p class="dataset-note">Showing the latest {runs.length} of {totalTrials} registered attempts. Older attempts remain stored and count toward the research search.</p>{/if}
{#if !runs.length}<div class="lab-empty"><span>↗</span><h3>Start with a testable idea.</h3><p>Run one experiment or compare portfolio sizes. Results and failed attempts will appear here.</p></div>{:else}<div class="table-scroll lab-run-scroll"><table><thead><tr><th>Hypothesis / dataset</th><th>Holdings</th><th>Status</th><th>Inspect</th></tr></thead><tbody>{#each runs as run}<tr class:selected-run={selected?.id===run.id}><td><strong>{methods[run.config.hypothesis]}</strong><small>{run.datasetName} · {new Date(run.createdAt).toLocaleString('en-GB')}</small></td><td>{run.config.topK}</td><td><span class="run-status" data-status={run.status}>{run.status}{run.status==='running'?` ${run.progress}%`:''}</span></td><td><button class="secondary small-button" onclick={()=>void inspect(run)} aria-label={`Inspect ${run.id.slice(0,8)}`}>Open</button></td></tr>{/each}</tbody></table></div>{/if}
{#if selected && ['queued','running'].includes(selected.status)}<div class="running-note" aria-live="polite"><p>{selected.status==='queued'?'Waiting for the research worker.':'Training and evaluating chronological folds.'}</p><progress max="100" value={selected.progress}></progress><button class="secondary small-button" onclick={()=>void cancel(selected!)}>Cancel experiment</button></div>{/if}
{#if selected?.errorCode}<div class="error" role="alert">{selected.errorCode==='tail-insufficient-examples'?'This training window has too few +50% six-month winners to fit the upside model responsibly. Use a larger suitable dataset or test another hypothesis.':`Experiment ${selected.status}: ${selected.errorCode}. The attempt remains recorded.`}</div>{/if}
</section></div>
{#if error}<p class="error" role="alert">{error}</p>{/if}
<StudyLab {datasets} onInspect={(id)=>void inspectStudyRun(id)} onUpdated={()=>void refresh()}/>
{#if report && candidate}
<section class="panel lab-results" aria-labelledby="results-title"><div class="panel-heading"><div><p class="eyebrow">{report.scope.replaceAll('_',' ').toUpperCase()}</p><h2 id="results-title">The result of the experiment</h2></div><span class="badge">{report.researchOnly?'NON-EXECUTABLE RESEARCH PORTFOLIOS':report.synthetic?'SYNTHETIC DATA':'EXPLORATORY IMPORT'}</span></div><p class="dataset-note">{report.evaluationStart}–{report.evaluationEnd} · {report.scope==='reserved_holdout'?'final evaluation window consumed from':'final data reserved from'} {report.reservedPeriodStart}. Policy: {report.config.allocationPolicy??'full-rebalance'}. End wealth includes contributions; returns below exclude deposits.</p>
<div class="lab-metrics"><div><span>Candidate ending value</span><strong>{money(candidate.endingEquityGbp)}</strong></div><div><span>Money contributed</span><strong>{money(candidate.contributionsGbp)}</strong></div><div><span>Net investment profit</span><strong>{money(candidate.profitGbp)}</strong></div><div><span>Largest unit-value fall</span><strong>{pct(candidate.maxDrawdown)}</strong></div></div>
<figure><div class="chart-key"><span><i class="balance-key"></i>Selected strategy</span><span>— Dataset benchmark</span><span>⋯ Cash / contributions</span></div><svg class="projection-chart" viewBox="0 0 800 260" role="img" aria-labelledby="backtest-chart-title"><title id="backtest-chart-title">Historical simulated balance comparison. An accessible results table follows.</title>{#each [0,.5,1] as level}<line class="grid-line" x1="45" x2="755" y1={220-level*185} y2={220-level*185}/><text class="axis-label" x="42" y={215-level*185}>{money(chartMax*level)}</text>{/each}<polyline class="deposit-line" points={curve('cash')}/><polyline class="benchmark-line" points={curve('benchmark')}/><polyline class="balance-line" points={curve('candidate')}/><text class="axis-label" x="45" y="250">{chartRows[0]?.periodEnd}</text><text class="axis-label" text-anchor="end" x="755" y="250">{chartRows.at(-1)?.periodEnd}</text></svg></figure>
<div class="table-scroll"><table><caption>Identical deposits and evaluation dates; flat costs applied to invested comparators</caption><thead><tr><th>Strategy</th><th>Ending GBP</th><th>Profit GBP</th><th>Annualised return</th><th>Max drawdown</th><th>Trading costs</th></tr></thead><tbody>{#each report.summaries as s}<tr><td>{report.config.allocationPolicy==='contribution-only'&&s.strategy==='equal_weight'?'All assets, buy-only equal targets':labels[s.strategy]}</td><td>{money(s.endingEquityGbp)}</td><td>{money(s.profitGbp)}</td><td>{pct(s.annualisedTimeWeightedReturn)}</td><td>{pct(s.maxDrawdown)}</td><td>{money(s.tradingCostGbp)}</td></tr>{/each}</tbody></table></div></section>
{#if selected&&report.scope==='development_walk_forward'}<SearchDiagnostics anchorRunId={selected.id}/>{/if}
<div class="bottom-grid"><section class="panel compact"><p class="eyebrow">HISTORICAL MODEL CHOICES</p><h2>Ranked holdings at {lastDate}</h2><p>These are the model's historical choices. Scores rank the research universe; they are not calibrated probabilities. Cash absorbs unused allocation.</p><div class="table-scroll"><table><thead><tr><th>Asset</th><th>Score</th><th>Target allocation</th></tr></thead><tbody>{#each picks as p}<tr><td>{p.symbol}</td><td>{p.score.toFixed(4)}</td><td>{pct(p.targetWeight)}</td></tr>{/each}</tbody></table></div><p class="dataset-note">Feature cutoff: {picks[0]?.featureCutoff}. Synthetic symbols and research portfolios cannot become broker signals.</p></section><section class="panel compact"><p class="eyebrow">FORWARD SCENARIOS</p><h2>If this sampled regime repeated…</h2><p>Conditional paths from six-month blocks of net candidate returns. The range describes resampled scenarios, not a calibrated chance of future wealth.</p><figure><svg class="projection-chart" viewBox="0 0 800 260" role="img" aria-label="Conditional forward balance scenarios with 10th, median and 90th path quantiles"><polygon class="forward-band" points={band}/><polyline class="deposit-line" points={forwardLine('contributionsGbp')}/><polyline class="balance-line" points={forwardLine('medianBalanceGbp')}/><text class="axis-label" x="45" y="250">Now</text><text class="axis-label" x="755" y="250" text-anchor="end">Year {report.forward.points.at(-1)?.year}</text></svg></figure><details><summary>Scenario values and assumptions</summary><div class="table-scroll"><table><thead><tr><th>Year</th><th>Lower</th><th>Median</th><th>Upper</th></tr></thead><tbody>{#each report.forward.points as p}<tr><td>{p.year}</td><td>{money(p.lowerBalanceGbp)}</td><td>{money(p.medianBalanceGbp)}</td><td>{money(p.upperBalanceGbp)}</td></tr>{/each}</tbody></table></div><p class="dataset-note">{report.forward.method}</p></details></section></div>
<section class="panel compact evidence-intro"><p class="eyebrow">EVIDENCE AND LIMITS</p><h2>A result is not a trading permission.</h2><p>{report.source}</p><ul class="limitations">{#each report.limitations as limitation}<li>{limitation}</li>{/each}</ul><p class="dataset-note">Dataset {report.datasetSha256.slice(0,16)}… · {report.featureVersion} · Every run retains model parameters, predictions, trades and original configuration.</p><a class="text-link" href="#execution">Inspect the decision-to-order path ↗</a></section>
{/if}
